negativeExample:
import org.eclipse.core.resources.IFile;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.NullProgressMonitor;
import java.io.ByteArrayInputStream;

public class NegativeTestClass {
    public void testOtherMethod(IFile file) throws CoreException {
        byte[] content = "test".getBytes();
        IProgressMonitor monitor = new NullProgressMonitor();

        // This should not be matched as it's a different method
        file.create(new ByteArrayInputStream(content), IFile.FORCE, monitor);

        // This should not be matched as it's a different method with different arguments
        file.append(new ByteArrayInputStream(content), IFile.FORCE, monitor);
    }
}
